/** Real app ADB, service activation and default assignment on disposable Android9/14 only. */
public final class RuntimeSetupCheck extends Instrumentation {
 private Context c;private UiAutomation ui;private int checks;private final StringBuilder log=new StringBuilder();private ExpertBackend adb;private AccessActivity screen;private String oldServices,oldEnabled,oldOwnGate,oldProbeGate,otherHome,endpoint="127.0.0.1:5555";
 public void onCreate(Bundle b){super.onCreate(b);endpoint=b.getString("endpoint","127.0.0.1:5555");start();}
 private void check(boolean ok,String text){log.append(ok?"PASS ":"FAIL ").append(text).append('\n');checks++;android.util.Log.i("TrueTVRecovery",(ok?"PASS ":"FAIL ")+text);if(!ok)throw new AssertionError(text);}
 private void main(Runnable job){Throwable[] failure={null};runOnMainSync(()->{try{job.run();}catch(Throwable e){failure[0]=e;}});waitForIdleSync();if(failure[0]!=null)throw new AssertionError(failure[0]);}
 private Object field(Object obj,String name){try{Field f=obj.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(obj);}catch(Exception e){throw new AssertionError(e);}}
 private AccessibilityNodeInfo id(AccessibilityNodeInfo n,String value){if(n==null)return null;if(value.equals(n.getViewIdResourceName()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo found=id(n.getChild(i),value);if(found!=null)return found;}return null;}
 private void clearKnownVm(){AccessibilityNodeInfo root=ui.getRootInActiveWindow();if(root!=null&&"android".contentEquals(root.getPackageName())&&(!root.findAccessibilityNodeInfosByText("System UI isn't responding").isEmpty()||!root.findAccessibilityNodeInfosByText("Process system isn't responding").isEmpty())){AccessibilityNodeInfo wait=id(root,"android:id/aerr_wait");if(wait!=null)wait.performAction(AccessibilityNodeInfo.ACTION_CLICK);}}
 private String shell(String command)throws Exception {try(ParcelFileDescriptor fd=ui.executeShellCommand(command);InputStream in=new FileInputStream(fd.getFileDescriptor());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}}
 private boolean enabled(String target){android.view.accessibility.AccessibilityManager m=(android.view.accessibility.AccessibilityManager)c.getSystemService(Context.ACCESSIBILITY_SERVICE);for(android.accessibilityservice.AccessibilityServiceInfo i:m.getEnabledAccessibilityServiceList(-1))if(i.getId()!=null&&AccessibilitySettings.component(i.getId()).equals(target))return true;return false;}
 private void clickConfirm()throws Exception {long until=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<until){clearKnownVm();ArrayList<AccessibilityNodeInfo> roots=new ArrayList<>();roots.add(ui.getRootInActiveWindow());for(AccessibilityWindowInfo window:ui.getWindows())roots.add(window.getRoot());for(AccessibilityNodeInfo root:roots){if(root!=null&&(!root.findAccessibilityNodeInfosByText("Enable selected services through ADB?").isEmpty()||!root.findAccessibilityNodeInfosByText("Включить выбранные службы через ADB?").isEmpty())){AccessibilityNodeInfo yes=id(root,"android:id/button1");if(yes!=null){check(yes.performAction(AccessibilityNodeInfo.ACTION_CLICK),"explicit service-enable confirmation clicked");return;}}}Thread.sleep(100);}throw new AssertionError("No own enable confirmation");}
 private String gateMode(String text){for(String line:text.split("\\r?\\n"))if(line.trim().startsWith("ACCESS_RESTRICTED_SETTINGS:")){String mode=line.substring(line.indexOf(':')+1).trim().split("[;\\s]",2)[0];if(Arrays.asList("allow","ignore","deny","default").contains(mode))return mode;}return "default";}
 private void invoke(String method){try{Method m=screen.getClass().getDeclaredMethod(method);m.setAccessible(true);m.invoke(screen);}catch(Exception e){throw new AssertionError(e);}}
 private void freezeChecks()throws Exception {
  final String stock=ComponentName.unflattenFromString(otherHome).getPackageName();int original=c.getPackageManager().getApplicationEnabledSetting(stock);
  try{
   adb.shell("cmd package set-home-activity --user 0 "+otherHome);
   // Only the priority report / ignored preference are simulated; all disable/restore/state reads are real ADB.
   RestrictedOps.Runner priority=cmd->{boolean disabled=SystemCommands.confirmed(SystemCommands.Operation.DISABLE,stock,adb.shell(SystemCommands.query(SystemCommands.Operation.DISABLE,stock,0)).text);if(!cmd.endsWith(" -p ru.truetv.launcher")){if(cmd.equals(HomeDefaults.query(0))&&!disabled)return new ShellReply(0,"priority=2 preferredOrder=0\n"+otherHome);if(cmd.startsWith("cmd package set-home-activity")&&cmd.endsWith(" ru.truetv.launcher/ru.truetv.launcher.HomeActivity")&&!disabled)return new ShellReply(0,"Success");}return adb.shell(cmd);};
   HomeDefaults.freezeCurrent(priority,stock,0,Build.VERSION.SDK_INT,original);check(SystemCommands.confirmed(SystemCommands.Operation.DISABLE,stock,adb.shell(SystemCommands.query(SystemCommands.Operation.DISABLE,stock,0)).text),"explicit handoff actually freezes selected stock Home over ADB (priority report simulated)");check(HomeDefaults.isOwn(adb.shell(HomeDefaults.query(0)).text),"real Android resolves True TV after verified stock freeze");
   adb.shell("pm "+(original==0?"default-state":"enable")+" --user 0 "+stock);adb.shell("cmd package set-home-activity --user 0 "+otherHome);
   RestrictedOps.Runner rejected=cmd->{boolean disabled=SystemCommands.confirmed(SystemCommands.Operation.DISABLE,stock,adb.shell(SystemCommands.query(SystemCommands.Operation.DISABLE,stock,0)).text);if(cmd.equals(HomeDefaults.query(0))&&disabled)return new ShellReply(0,"other.home/.Unavailable");return priority.run(cmd);};
   boolean failed=false;try{HomeDefaults.freezeCurrent(rejected,stock,0,Build.VERSION.SDK_INT,original);}catch(java.io.IOException expected){failed=expected.getMessage().contains("previous stock Home state was restored");}check(failed,"unconfirmed own Home triggers explicit rollback result");check(c.getPackageManager().getApplicationEnabledSetting(stock)==original,"actual stock Home enabled setting restored exactly after failed switch");check(adb.shell(HomeDefaults.query(0)).text.contains(otherHome)||adb.shell(HomeDefaults.query(0)).text.contains(stock+"/.Launcher"),"actual previous Home resolves again after rollback");
  }finally{adb.shell("pm "+(original==0?"default-state":"enable")+" --user 0 "+stock);adb.shell("cmd package set-home-activity --user 0 "+otherHome);}
 }
 public void onStart(){c=getTargetContext();Bundle result=new Bundle();ExecutorService worker=Executors.newSingleThreadExecutor();try{
  check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"disposable VM guard SDK"+Build.VERSION.SDK_INT);ui=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);android.accessibilityservice.AccessibilityServiceInfo service=ui.getServiceInfo();service.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ui.setServiceInfo(service);
  Future<ExpertBackend> connection=worker.submit(()->new ExpertBackend(c,false,endpoint));long until=SystemClock.uptimeMillis()+55000;while(!connection.isDone()&&SystemClock.uptimeMillis()<until){clearKnownVm();AccessibilityNodeInfo root=ui.getRootInActiveWindow();if(root!=null&&!root.findAccessibilityNodeInfosByText("Allow USB debugging?").isEmpty()){AccessibilityNodeInfo yes=id(root,"android:id/button1");if(yes!=null)yes.performAction(AccessibilityNodeInfo.ACTION_CLICK);}Thread.sleep(120);}adb=connection.get(1,TimeUnit.SECONDS);check(adb.shell("id -u").text.trim().equals("2000")||adb.shell("id -u").text.trim().equals("0"),"real app ADB connection and same-device proof");
  new SettingsStore(c).data.edit().putString("access_endpoint",endpoint).putBoolean("bt_asked",true).putBoolean("bt_count",false).commit();for(android.content.pm.ResolveInfo home:c.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),0))if(home.activityInfo.packageName.equals("com.android.launcher3"))otherHome=new ComponentName(home.activityInfo.packageName,home.activityInfo.name).flattenToString();check(otherHome!=null,"stock Home fixture resolved on this Android version");oldServices=adb.shell(AccessibilitySettings.read(0,"enabled_accessibility_services")).text;oldEnabled=adb.shell(AccessibilitySettings.read(0,"accessibility_enabled")).text;
  String own=AccessibilitySettings.component("ru.truetv.launcher/.ControlService"),probe=AccessibilitySettings.component("ru.truetv.probe/.ProbeAccess");
  if(Build.VERSION.SDK_INT>=33){oldProbeGate=gateMode(adb.shell(RestrictedOps.command("ru.truetv.probe",0,false)).text);oldOwnGate=gateMode(adb.shell(RestrictedOps.command(c.getPackageName(),0,false)).text);adb.shell("cmd appops set --user 0 ru.truetv.probe ACCESS_RESTRICTED_SETTINGS ignore");check(!RestrictedOps.allowed(adb.shell(RestrictedOps.command("ru.truetv.probe",0,false)).text),"fixture starts with restricted-settings gate blocked");adb.shell("cmd appops set --user 0 ru.truetv.launcher ACCESS_RESTRICTED_SETTINGS ignore");check(!RestrictedOps.allowed(adb.shell(RestrictedOps.command(c.getPackageName(),0,false)).text),"own gate blocked before explicit UI action");RestrictedOps.grant(adb::shell,"ru.truetv.probe",0,Build.VERSION.SDK_INT);check(RestrictedOps.allowed(adb.shell(RestrictedOps.command("ru.truetv.probe",0,false)).text),"real Android13+ restricted-settings app-op confirmed");}
  AccessibilitySettings.enable(adb::shell,Arrays.asList(probe),0);until=SystemClock.uptimeMillis()+15000;while(!enabled(probe)&&SystemClock.uptimeMillis()<until)Thread.sleep(100);check(enabled(probe),"fixture service enabled before selection");
  screen=(AccessActivity)startActivitySync(new Intent(c,AccessActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ListView list=(ListView)field(screen,"list");until=SystemClock.uptimeMillis()+15000;while(list.getCount()<2&&SystemClock.uptimeMillis()<until)Thread.sleep(100);int at=-1;for(int i=0;i<list.getCount();i++)if(((AccessActivity.Entry)list.getAdapter().getItem(i)).component.equals(own))at=i;check(at>=0,"own concrete service selectable in UI");LinearLayout buttons=(LinearLayout)((ViewGroup)((ViewGroup)screen.findViewById(android.R.id.content)).getChildAt(0)).getChildAt(2);Button enable=(Button)buttons.getChildAt(0);for(int loop=0;loop<3;loop++){main(()->{list.setSelection(0);list.requestFocusFromTouch();});sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();check(enable.hasFocus(),"actual Dpad Up from service list selects first EnableADB button, cycle"+loop);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);waitForIdleSync();check(buttons.getChildAt(1).hasFocus(),"Right reaches second connection button");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);waitForIdleSync();check(list.hasFocus(),"Down from connection returns to service list");}check(!(Boolean)field(screen,"busy"),"remote focus movement never connects or grants");final int index=at;main(()->list.performItemClick(list.getAdapter().getView(index,null,list),index,index));main(enable::performClick);check(!enabled(own),"selection and opening confirmation do not enable service");clickConfirm();until=SystemClock.uptimeMillis()+25000;while((!enabled(own)||(Boolean)field(screen,"busy"))&&SystemClock.uptimeMillis()<until){clearKnownVm();Thread.sleep(150);}check(enabled(own),"UI activation confirmed by Android AccessibilityManager");check(enabled(probe),"pre-existing fixture service preserved");boolean resultReady=false;long resultUntil=SystemClock.uptimeMillis()+10000;while(!resultReady&&SystemClock.uptimeMillis()<resultUntil){clearKnownVm();AccessibilityNodeInfo dialogRoot=ui.getRootInActiveWindow();resultReady=dialogRoot!=null&&(!dialogRoot.findAccessibilityNodeInfosByText("TV Access: result").isEmpty()||!dialogRoot.findAccessibilityNodeInfosByText("TV Access: результат").isEmpty())&&id(dialogRoot,"android:id/button1")!=null&&"OK".contentEquals(id(dialogRoot,"android:id/button1").getText());if(!resultReady)Thread.sleep(100);}check(resultReady,"activation result primary action is OK, not hidden OEM Accessibility menu");main(()->check(ControlService.connected()!=null,"actual launcher AccessibilityService connected"));if(Build.VERSION.SDK_INT>=33)check(RestrictedOps.allowed(adb.shell(RestrictedOps.command(c.getPackageName(),0,false)).text),"own restricted-settings gate allowed before activation");
  AccessibilitySettings.disable(adb::shell,Arrays.asList(own),0);until=SystemClock.uptimeMillis()+10000;while(enabled(own)&&SystemClock.uptimeMillis()<until)Thread.sleep(100);check(!enabled(own)&&enabled(probe),"real deactivation removes only selected service and preserves fixture");
  AccessibilitySettings.disable(adb::shell,Arrays.asList(probe),0);check(!AccessibilitySettings.parse(adb.shell(AccessibilitySettings.read(0,"enabled_accessibility_services")).text).contains(probe),"last test service can be disabled through product command");
  check(adb.shell(Build.VERSION.SDK_INT>=29?"cmd role add-role-holder --user 0 android.app.role.HOME com.android.launcher3 1":"cmd package set-home-activity --user 0 "+otherHome).code==0&&!HomeDefaults.isOwn(adb.shell(HomeDefaults.query(0)).text),"different Home fixture assigned before mutation");HomeDefaults.assign(adb::shell,0,Build.VERSION.SDK_INT);check(HomeDefaults.isOwn(adb.shell(HomeDefaults.query(0)).text),"actual app ADB permanently assigns own Home");shell("input keyevent 3 3");Thread.sleep(500);check(HomeDefaults.isOwn(adb.shell(HomeDefaults.query(0)).text),"quick double Home preserves confirmed default");
  if(Build.VERSION.SDK_INT>=24&&Build.VERSION.SDK_INT<=28)freezeChecks();
  result.putBoolean("passed",true);result.putString("report",log+"Checks="+checks);
 }catch(Throwable e){try{android.graphics.Bitmap bitmap=ui.takeScreenshot();if(bitmap!=null){try(FileOutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"217-runtime-failure-api"+Build.VERSION.SDK_INT+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}}catch(Exception ignored){}StringWriter trace=new StringWriter();e.printStackTrace(new PrintWriter(trace));result.putBoolean("passed",false);result.putString("report",log.toString()+trace);}finally{try{if(adb!=null)adb.close();if(oldServices!=null){String value=oldServices.trim();if(value.equals("null")||value.isEmpty())shell("settings delete secure enabled_accessibility_services");else{AccessibilitySettings.parse(value);shell("settings --user 0 put secure enabled_accessibility_services '"+value+"'");}}if(oldEnabled!=null){if(oldEnabled.trim().equals("null"))shell("settings delete secure accessibility_enabled");else shell("settings --user 0 put secure accessibility_enabled "+(oldEnabled.trim().equals("1")?"1":"0"));}if(oldOwnGate!=null)shell("cmd appops set --user 0 ru.truetv.launcher ACCESS_RESTRICTED_SETTINGS "+oldOwnGate);if(oldProbeGate!=null)shell("cmd appops set --user 0 ru.truetv.probe ACCESS_RESTRICTED_SETTINGS "+oldProbeGate);if(otherHome!=null)shell(Build.VERSION.SDK_INT>=29?"cmd role add-role-holder --user 0 android.app.role.HOME com.android.launcher3 1":"cmd package set-home-activity --user 0 "+otherHome);if(screen!=null)main(screen::finish);}catch(Exception ignored){}worker.shutdownNow();}finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
